-- Miranoir catalogue: 153 stones. Run AFTER schema.sql.
-- This replaces the whole stones table with the catalogue, so only run it
-- once at the start (running it again would undo edits made in the admin).
-- Photos are served by the website itself from /public/catalog.
begin;
delete from stones;
commit;

-- check: should list 8 collections with their counts
select collection, count(*) from stones group by collection order by collection;
